Translate("deDE", "excavation-site", {
	title = "Excavation Site",
	aliases = { "Excavation Site: Wetlands" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hoch in den Hügeln des {link:wetlands}Sumpflands{/link}, oberhalb des verwüsteten Lagers von {link:whelgar-s-excavation-site}Whelgars Ausgrabungsstätte{/link}, liegt ein Ort, der von der Zeit zurückgelassen scheint. Seit einiger Zeit zieht dort ein seltsamer Nebel von den Bergen herab, und nachts blitzen Lichter auf den Höhen. Ein zweites Lager steht zwischen den Felsen, mit Zelten und Kisten und riesigen gehörnten Schädeln, die halb im Boden stecken, und einem großen grünen Stein hinter einer hölzernen Barrikade. Dahinter, unter einem hohen Baum, öffnet sich eine Säule aus blauem Nebel in die Erde. Was unten wartet, ist älter als jede Zwergenfeste.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet, wer die uralten Orte unter dem Hochland schuf oder wann. Die Ausgräber der {link:explorers-league}Forscherliga{/link} in der Marsch darunter haben gewaltige Knochen gefunden und eine Tafel in der Schrift der Titanen, den {link:goaz-stone}Goaz-Stein{/link}, der von Alten Göttern spricht, die unter dem Land angekettet sind. Ob die Tafel und die Gewölbe des Hochlands Teil einer einzigen Geschichte sind, konnte noch kein Gelehrter sagen. Bekannt ist, dass die Konstrukte der Titanen hier erwacht sind und dass sie vom rechten Weg abgekommen sind.]=],
		},
		{
			title = "Der Abstieg",
			text = [=[Der Weg hinab führt durch vier Orte, denen die Ausgräber Namen gegeben haben. Die Lost Dig Site ist, was von einem Lager übrig ist, das zu tief gegraben hat. Stalker's Thicket ist ein Gewirr aus Pflanzen, in dem Raptoren im Rudel jagen. Die Lost Marsh ist eine überflutete Höhle aus Schilf und schwarzem Wasser, in der riesige Schädel zwischen den Binsen liegen und Krokilisken unter der Oberfläche dahingleiten. Am Ende liegt die Site of the Guardian, ein Gewölbe aus großen behauenen Steinen.]=],
		},
		{
			title = "Die in der Tiefe hausen",
			text = [=[• {b}{link:saltspine}Saltspine{/link}{/b}, ein bleicher Krokilisk von großem Alter und gewaltiger Größe.
• {b}{link:shadetooth}Shadetooth{/link}{/b}, ein Raptor, größer als jeder in der Marsch darüber, mit einem eigenen Jagdrudel.
• {b}{link:highland-horror}Der Highland Horror{/link}{/b}, ein ungeheuerliches Ding aus Schlamm und Fäulnis, das sich aus dem Moor erhebt.
• {b}Der {link:relic-guardian}Relic Guardian{/link}{/b}, ein Konstrukt aus grauem Stein, das noch immer das Gewölbe hütet, zu dessen Hut es geschaffen wurde.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Die {link:explorers-league}Forscherliga{/link} hat gute Gründe, sich für das zu interessieren, was dort unten liegt. Ihre Kollegen in {link:whelgar-s-excavation-site}Whelgars Ausgrabungsstätte{/link} haben für die Geheimnisse des Sumpflands bereits teuer bezahlt, und die Überlebenden sitzen noch immer auf ihrem Felsvorsprung fest. Die Geschöpfe des Hochlands, Schildkröten, Spinnen und lauernde Bestien, sind rund um das Portal dreist geworden.]=],
		},
	},
})

